{
  "story": [
    {
      "page1": "Lumi the firefly was very small. She had a little light."
    },
    {
      "page2": "The other fireflies had bright, strong lights. Lumi's light felt dim."
    },
    {
      "page3": "She felt a little sad. She wished she was a brave firefly."
    },
    {
      "page4": "One night, a big, dark shadow fell. \"Oh no!\" thought Lumi, scared."
    },
    {
      "page5": "She closed her eyes. \"This is okay,\" she whispered. \"I am brave, I am brave.\""
    },
    {
      "page6": "Lumi opened her eyes. She blinked her little light. She must be a brave little firefly."
    },
    {
      "page7": "The shadow was just a branch! Lumi's light showed the way for everyone."
    },
    {
      "page8": "Lumi's little light felt strong and bright now. She *felt a little sad* no more!"
    }
  ]
}

